input.script:
companies = boundary retry 2 {
    return list_companies({})
} catch err {
    return fail("COMPANIES_FAILED", err.code + ": " + err.message)
}
by_domain = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}
first = boundary retry 2 {
    return list_contacts({ page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
rest = for page in list.range(2, first.total_pages + 1) {
    r = boundary retry 2 {
        return list_contacts({ page })
    } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return r.items
}
contacts = fold acc = first.items for page in rest { return acc + page }
results = for contact in contacts {
    has_phone = contact.phone != null and contact.phone != ""
    already_valid = if has_phone { regex.test(contact.phone, "^\\+1\\d{10}$") } else { true }
    digits = regex.replace(contact.phone, "[^0-9]", "") if has_phone
    newphone = if has_phone and text.length(digits) == 10 {
        "+1" + digits
    } else if has_phone and text.length(digits) == 11 and text.starts_with(digits, "1") {
        "+" + digits
    } else {
        contact.phone
    }
    phone_fix = already_valid == false and newphone != contact.phone
    email = contact.email if contact.email != null else ""
    parts = text.split(email, "@")
    domain = parts[1] if list.length(parts) == 2 else ""
    company_empty = contact.company == null or contact.company == ""
    fill = by_domain[domain] if company_empty and domain in by_domain and domain != "" else null
    updated = boundary retry 2 {
        return update_contact({ id: contact.id, phone: newphone if phone_fix, company: fill })
    } catch err {
        return fail("UPDATE_FAILED", err.code + ": " + err.message)
    } if phone_fix or fill != null
    return { phone_fixed: phone_fix, company_filled: fill != null }
}
phones_fixed = fold acc = 0 for r in results { return acc + (1 if r.phone_fixed else 0) }
companies_filled = fold acc = 0 for r in results { return acc + (1 if r.company_filled else 0) }
submitted = submit_result({ answer: { phones_fixed, companies_filled } })
return { phones_fixed, companies_filled, recorded: submitted.recorded }
